import React, { useState, useEffect } from 'react';
import { Theme, Supplier, Shop, PhoneNumber } from '../types';
import Icon from './Icon';
import PhoneInput from './PhoneInput';
import MultiSelectDropdown from './MultiSelectDropdown';
import { allAfricanCountries } from '../data';

interface SupplierModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (data: Partial<Supplier>) => void;
    initialData?: Supplier | null;
    theme: Theme;
    shops: Shop[];
    isEdit?: boolean;
}

const warehouses = [
    { id: 101, name: 'Main Warehouse - Kampala' },
    { id: 102, name: 'Distribution Center - Jinja' },
    { id: 103, name: 'Storage Unit B' }
];

const SupplierModal: React.FC<SupplierModalProps> = ({ isOpen, onClose, onSave, initialData, theme, shops, isEdit = false }) => {
    const [isClosing, setIsClosing] = useState(false);
    const [locationType, setLocationType] = useState<'Shop' | 'Warehouse'>('Shop');

    const [formData, setFormData] = useState<{
        shopIds: string[];
        companyName: string;
        email: string;
        email2: string;
        email3: string;
        phone: PhoneNumber;
        phone2: PhoneNumber;
        phone3: PhoneNumber;
        country: string;
        firstName: string;
        lastName: string;
        otherName: string;
        remarks: string;
    }>({
        shopIds: [],
        companyName: '',
        email: '',
        email2: '',
        email3: '',
        phone: { code: '+256', number: '' },
        phone2: { code: '+256', number: '' },
        phone3: { code: '+256', number: '' },
        country: '',
        firstName: '',
        lastName: '',
        otherName: '',
        remarks: ''
    });

    useEffect(() => {
        if (isOpen) {
            if (initialData) {
                setLocationType(initialData.locationType || 'Shop');
                setFormData({
                    shopIds: initialData.shopIds.map(String),
                    companyName: initialData.companyName,
                    email: initialData.email,
                    email2: initialData.email2 || '',
                    email3: initialData.email3 || '',
                    phone: initialData.phone,
                    phone2: initialData.phone2 || { code: '+256', number: '' },
                    phone3: initialData.phone3 || { code: '+256', number: '' },
                    country: initialData.country,
                    firstName: initialData.contactPerson.firstName,
                    lastName: initialData.contactPerson.lastName,
                    otherName: initialData.contactPerson.otherName || '',
                    remarks: initialData.remarks || ''
                });
            } else {
                // Reset for Add mode
                 setFormData({
                    shopIds: [],
                    companyName: '',
                    email: '',
                    email2: '',
                    email3: '',
                    phone: { code: '+256', number: '' },
                    phone2: { code: '+256', number: '' },
                    phone3: { code: '+256', number: '' },
                    country: '',
                    firstName: '',
                    lastName: '',
                    otherName: '',
                    remarks: ''
                });
                setLocationType('Shop');
            }
            setIsClosing(false);
        }
    }, [isOpen, initialData]);

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => onClose(), 300);
    };

    const handleSave = () => {
        // Basic Validation
        if (!formData.companyName) {
             alert("Company Name is required.");
             return;
        }
        if (!formData.firstName || !formData.lastName) {
            alert("Contact Person (First & Last Name) is required.");
            return;
        }
        if (!formData.email) {
            alert("Primary Email Address is required.");
            return;
        }
        if (!formData.phone.number) {
            alert("Primary Phone Number is required.");
            return;
        }

        const supplierData: Partial<Supplier> = {
            companyName: formData.companyName,
            shopIds: formData.shopIds.map(Number),
            shopName: locationType === 'Shop' 
                ? (formData.shopIds.length > 0 ? shops.find(s => s.id.toString() === formData.shopIds[0])?.name || 'Multiple' : 'None')
                : (formData.shopIds.length > 0 ? warehouses.find(w => w.id.toString() === formData.shopIds[0])?.name || 'Multiple' : 'None'),
            locationType: locationType,
            email: formData.email,
            email2: formData.email2,
            email3: formData.email3,
            phone: formData.phone,
            phone2: formData.phone2,
            phone3: formData.phone3,
            country: formData.country,
            contactPerson: {
                firstName: formData.firstName,
                lastName: formData.lastName,
                otherName: formData.otherName
            },
            remarks: formData.remarks
        };
        onSave(supplierData);
        handleClose();
    };

    const handleLocationChange = (selectedIds: string[]) => {
        setFormData(prev => ({ ...prev, shopIds: selectedIds }));
    };

    const handleLocationTypeChange = (type: 'Shop' | 'Warehouse') => {
        setLocationType(type);
        setFormData(prev => ({ ...prev, shopIds: [] })); // Reset selection on type change
    };

    if (!isOpen && !isClosing) return null;

    const inputClass = `w-full px-3 py-2 rounded-md border focus:outline-none focus:ring-1 focus:ring-yellow-500 text-sm ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-900'}`;
    const labelClass = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    // Determine available options based on location type
    const locationOptions = locationType === 'Shop' 
        ? shops.map(s => ({ id: s.id.toString(), name: s.name })) 
        : warehouses.map(w => ({ id: w.id.toString(), name: w.name }));

    return (
        <div className={`fixed inset-0 z-[80] flex items-center justify-center bg-black/60 p-4 transition-opacity duration-300 ${isOpen && !isClosing ? 'opacity-100' : 'opacity-0'}`}>
            <div className={`w-full max-w-3xl rounded-lg shadow-xl flex flex-col max-h-[95vh] transform transition-all duration-300 ${isClosing ? 'scale-95 opacity-0' : 'scale-100 opacity-100'} ${theme === 'dark' ? 'bg-slate-900' : 'bg-white'}`}>
                <div className={`flex justify-between items-center p-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <h2 className={`text-xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>
                        {isEdit ? 'Edit Supplier' : 'New Supplier'}
                    </h2>
                    <button onClick={handleClose} className={`${theme === 'dark' ? 'text-slate-400 hover:text-slate-200' : 'text-slate-500 hover:text-slate-800'}`}>
                        <Icon name="x-mark" className="h-6 w-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto space-y-6">
                    {/* Location Section */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                         <div>
                            <label className={labelClass}>Location Type</label>
                            <select 
                                value={locationType} 
                                onChange={(e) => handleLocationTypeChange(e.target.value as 'Shop' | 'Warehouse')} 
                                className={inputClass}
                            >
                                <option value="Shop">Shop</option>
                                <option value="Warehouse">Warehouse</option>
                            </select>
                        </div>
                        <div className="md:col-span-2">
                            <label className={labelClass}>{locationType}(s)</label>
                             <MultiSelectDropdown 
                                 theme={theme}
                                 options={locationOptions.map(o => o.name)}
                                 selected={formData.shopIds.map(id => locationOptions.find(o => o.id === id)?.name || '').filter(Boolean)}
                                 onChange={(selectedNames) => {
                                     const ids = selectedNames.map(name => locationOptions.find(o => o.name === name)?.id).filter(Boolean) as string[];
                                     handleLocationChange(ids);
                                 }}
                                 placeholder={`Select ${locationType.toLowerCase()}(s)`}
                             />
                        </div>
                    </div>

                    {/* Company Info */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className={labelClass}>Company or Business Name <span className="text-red-500">*</span></label>
                            <input type="text" className={inputClass} value={formData.companyName} onChange={e => setFormData({...formData, companyName: e.target.value})} />
                        </div>
                         <div>
                            <label className={labelClass}>Country</label>
                            <select className={inputClass} value={formData.country} onChange={e => setFormData({...formData, country: e.target.value})}>
                                <option value="">Select Country</option>
                                {allAfricanCountries.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                            </select>
                        </div>
                    </div>

                    {/* Emails - Row of 3 */}
                    <div>
                         <label className={labelClass}>Email Addresses</label>
                         <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                             <div>
                                <input type="email" className={inputClass} value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} placeholder="Primary Email *" />
                             </div>
                             <div>
                                <input type="email" className={inputClass} value={formData.email2} onChange={e => setFormData({...formData, email2: e.target.value})} placeholder="Email 2 (Optional)" />
                             </div>
                             <div>
                                <input type="email" className={inputClass} value={formData.email3} onChange={e => setFormData({...formData, email3: e.target.value})} placeholder="Email 3 (Optional)" />
                             </div>
                         </div>
                    </div>

                    {/* Phone Numbers - Row of 3 */}
                    <div>
                        <label className={labelClass}>Phone Numbers</label>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                             <div>
                                <PhoneInput theme={theme} value={formData.phone} onChange={(val) => setFormData({...formData, phone: val})} />
                                <span className={`text-[10px] ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>Primary *</span>
                            </div>
                             <div>
                                <PhoneInput theme={theme} value={formData.phone2} onChange={(val) => setFormData({...formData, phone2: val})} />
                                <span className={`text-[10px] ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>Secondary</span>
                            </div>
                             <div>
                                <PhoneInput theme={theme} value={formData.phone3} onChange={(val) => setFormData({...formData, phone3: val})} />
                                <span className={`text-[10px] ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>Tertiary</span>
                            </div>
                        </div>
                    </div>

                    {/* Contact Person */}
                    <div>
                        <label className={`block text-sm font-medium mb-2 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>Contact Person</label>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div>
                                <label className={`text-xs mb-1 block ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>First Name *</label>
                                <input type="text" className={inputClass} value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} />
                            </div>
                            <div>
                                <label className={`text-xs mb-1 block ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Last Name *</label>
                                <input type="text" className={inputClass} value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} />
                            </div>
                            <div>
                                <label className={`text-xs mb-1 block ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Other Name</label>
                                <input type="text" className={inputClass} value={formData.otherName} onChange={e => setFormData({...formData, otherName: e.target.value})} />
                            </div>
                        </div>
                    </div>

                    {/* Remarks */}
                    <div>
                        <label className={labelClass}>Remarks</label>
                        <textarea 
                            rows={3} 
                            className={`w-full px-3 py-2 rounded-md border focus:outline-none focus:ring-1 focus:ring-yellow-500 text-sm resize-none ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-900'}`} 
                            value={formData.remarks} 
                            onChange={e => setFormData({...formData, remarks: e.target.value})}
                            placeholder="Additional notes..."
                        >
                        </textarea>
                         <div className="flex justify-end -mt-6 mr-2 pointer-events-none">
                            <Icon name="analytics" className="h-4 w-4 opacity-20" /> 
                        </div>
                    </div>
                </div>

                <div className={`flex justify-end items-center p-6 border-t space-x-3 ${theme === 'dark' ? 'border-slate-700 bg-black/20' : 'border-slate-200 bg-slate-50'} rounded-b-lg`}>
                    <button onClick={handleClose} className={`px-6 py-2.5 text-sm font-medium border rounded-md shadow-sm ${theme === 'dark' ? 'text-slate-300 bg-transparent border-slate-600 hover:bg-slate-700' : 'text-slate-700 bg-white border-slate-300 hover:bg-slate-100'}`}>
                        <Icon name="x-mark" className="h-4 w-4 mr-2 inline" /> Cancel
                    </button>
                    <button onClick={handleSave} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-yellow-500 border border-transparent rounded-md shadow-sm hover:bg-yellow-600 flex items-center">
                        <Icon name="check-circle" className="h-4 w-4 mr-2" /> Save
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SupplierModal;
